<script lang="ts">
 import { onMount } from 'svelte';
 import { clearDrafts,drafts } from '$lib/offline';
 import { translator } from '$lib/app-i18n';import { authClient } from '$lib/auth-client';import { goto,invalidateAll } from '$app/navigation';import { page } from '$app/state';
 let {data,children}=$props();let t=$derived(translator(data.lang));let ready=$state(false);let name=$state(''),mode=$state('standalone'),message=$state(''),busy=$state(false),menu=$state(false);
 onMount(()=>{ready=true;if(data.tenant)localStorage.setItem('vinea-active-winery',data.tenant.id);localStorage.setItem('vinea-language',data.lang);});
 const sections=['today','vineyard','harvest','cellar','blends','lab','bottling','reports','data','admin'];
 async function create(){busy=true;const res=await fetch('/api/tenants',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,mode})});if(res.ok)await invalidateAll();else message=(await res.json()).message??'Error';busy=false;}
 async function discardDeviceDrafts(){if(data.tenant&&(await drafts(data.tenant.id)).length&&!confirm(t('discardConfirm')))return false;await clearDrafts();return true;}
 async function change(id:string){if(!await discardDeviceDrafts())return;await fetch('/api/tenants',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id})});await invalidateAll();}
</script>
<svelte:head><title>Vinea · {data.tenant?.name??t('winery')}</title></svelte:head>
<div class="shell"><aside class:visible={menu}><a class="brand" href="/app">Vinea<span>WINZERAPP</span></a>{#if data.tenant}<label class="winery"><span>{t('winery')}</span><select aria-label={t('winery')} value={data.tenant.id} onchange={(e)=>change(e.currentTarget.value)}>{#each data.tenants as tenant}<option value={tenant.id}>{tenant.name}</option>{/each}</select></label>{/if}<nav>{#each sections as s,i}<a class:active={page.url.pathname==='/app/'+s} href={'/app/'+s} onclick={()=>menu=false}><span class="navindex">{String(i+1).padStart(2,'0')}</span>{t(s)}</a>{/each}</nav><div class="sidebarbottom"><small>{data.user.name} · {data.tenant?t(data.tenant.role):''}</small><div class="languages">{#each ['de','en','it','fr'] as l}<a class:selected={l===data.lang} href={'?lang='+l}>{l.toUpperCase()}</a>{/each}</div><button class="quiet" onclick={async()=>{if(!await discardDeviceDrafts())return;await authClient.signOut();localStorage.removeItem('vinea-active-winery');await goto('/login');}}>{t('signout')}</button></div></aside><div class="workspace"><header><button class="mobile" onclick={()=>menu=!menu} aria-label="Menu">☰</button><span>{data.tenant?.name??'Vinea'}</span><small>{t('noPaid')}</small></header><main id="main">{#if !data.tenant}<div class="onboarding"><p class="eyebrow">VINEA</p><h1>{t('createWinery')}</h1><form onsubmit={(e)=>{e.preventDefault();create();}}><label>{t('name')}<input bind:value={name} required minlength="2" maxlength="120" /></label><label>{t('mode')}<select bind:value={mode}>{#each ['standalone','erp','companion'] as m}<option value={m}>{t(m)}</option>{/each}</select></label><button disabled={!ready||busy}>{t('createWinery')}</button></form>{#if message}<p role="alert">{message}</p>{/if}</div>{:else}{@render children()}{/if}</main></div></div>
<style>:global(body){margin:0;background:#f7f7f3;color:#263b32;font-family:Inter,system-ui,sans-serif;font-size:14px}:global(*){box-sizing:border-box}:global(button),:global(input),:global(select),:global(textarea){font:inherit}:global(input),:global(select),:global(textarea){padding:10px 12px;border:1px solid #d7ded5;border-radius:7px;background:#fff;color:#263b32;max-width:100%}:global(label){display:grid;gap:7px;font-size:12px;color:#5b6c60}:global(button){padding:11px 18px;background:#285741;color:white;border:0;border-radius:7px;cursor:pointer}:global(button:disabled){opacity:.5;cursor:wait}:global(a){color:#285741}:global(h1){font:36px Georgia,serif;font-weight:500;margin:8px 0 28px}:global(h2){font:23px Georgia,serif;font-weight:500}:global(h3){font-size:14px}:global(.eyebrow){font-size:10px;letter-spacing:2px;color:#748373}:global(.card){background:#fff;border:1px solid #e0e5dc;border-radius:12px;padding:22px;margin-bottom:20px}:global(.muted){color:#768174;font-size:12px}.shell{display:flex;min-height:100vh}aside{width:240px;position:fixed;inset:0 auto 0 0;padding:28px 20px;background:#fcfcf9;border-right:1px solid #e0e5dc;display:flex;flex-direction:column;z-index:10;overflow-y:auto}.brand{text-decoration:none;font:600 36px Georgia,serif}.brand span{display:block;font:9px system-ui;letter-spacing:3px;margin:6px 0 30px 3px}.winery{margin-bottom:26px}.winery select{width:100%;font-size:12px}nav{display:grid;gap:3px}nav a{padding:12px 10px;border-radius:7px;text-decoration:none;color:#687767;font-size:13px}nav a.active{background:#e8efe6;color:#244d36}.navindex{font-size:10px;opacity:.5;margin-right:14px}.sidebarbottom{margin-top:auto;padding-top:24px;display:grid;gap:15px}.sidebarbottom small{font-size:10px;color:#7c877b}.languages{display:flex;gap:15px;font-size:10px}.languages a{text-decoration:none}.languages a.selected{text-decoration:underline}.quiet{padding:0;text-align:left;font-size:11px;background:none;color:#657760}.workspace{width:100%;margin-left:240px}header{height:70px;padding:0 36px;border-bottom:1px solid #e4e7e0;display:flex;align-items:center;justify-content:space-between;background:#fff8}header small{color:#829078;font-size:10px}main{padding:35px;max-width:1500px;margin:auto}.onboarding{max-width:480px;margin:6vh auto}.onboarding form{display:grid;gap:22px}.mobile{display:none}@media(max-width:800px){aside{transform:translateX(-100%)}aside.visible{transform:none}.workspace{margin-left:0}.mobile{display:block}header{padding:0 20px}main{padding:22px 16px}header small{display:none}}</style>
